// rr_arbiter: round-robin arbiter for N requesters (default 4).
// Implements interface_spec.md and microarchitecture.md (rr_arbiter).
// Requirement: Create a round-robin arbiter for four requesters.
`timescale 1ns / 1ps
`default_nettype none

module rr_arbiter #(
    parameter integer N = 4
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire [N-1:0] req,
    output reg  [N-1:0] grant
);
    // Pointer width; N is 2 or more per the interface spec.
    localparam integer PW   = (N > 1) ? $clog2(N) : 1;
    // Index of the last requester; the search wraps here, not at 2**PW.
    localparam integer LAST = N - 1;

    // Microarchitecture section 1: the only state is the priority pointer.
    reg [PW-1:0] ptr;
    reg [PW-1:0] ptr_next;
    reg          found;
    integer      k;
    integer      idx;

    // Microarchitecture section 2: wrapping priority search from ptr.
    // Every output of the block gets a default before the loop (no latch).
    always @(*) begin
        grant    = {N{1'b0}};
        ptr_next = ptr;
        found    = 1'b0;
        idx      = {{(32-PW){1'b0}}, ptr};
        for (k = 0; k < N; k = k + 1) begin
            if (!found && req[idx]) begin
                grant[idx] = 1'b1;
                found      = 1'b1;
                // Microarchitecture section 3: one past the winner, wrapping at N.
                if (idx == LAST) ptr_next = {PW{1'b0}};
                else             ptr_next = idx[PW-1:0] + 1'b1;
            end
            if (idx == LAST) idx = 0;
            else             idx = idx + 1;
        end
    end

    // Microarchitecture sections 3 and 4: synchronous active-low reset to 0;
    // the pointer holds when nothing is granted.
    always @(posedge clk) begin
        if (!rst_n) ptr <= {PW{1'b0}};
        else        ptr <= ptr_next;
    end

`ifdef FORMAL
    // Design-intent assertions (microarchitecture section 5).
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    initial assume (!rst_n);

    // Independent reference: rotate, isolate the lowest set bit, rotate back.
    wire [2*N-1:0] f_req2  = {req, req} >> ptr;
    wire [N-1:0]   f_rot   = f_req2[N-1:0];
    wire [N-1:0]   f_pick  = f_rot & (~f_rot + 1'b1);
    wire [2*N-1:0] f_gnt2  = {f_pick, f_pick} << ptr;
    wire [N-1:0]   f_ref   = f_gnt2[2*N-1:N];
    // One past the winner, wrapping at N.
    wire [N-1:0]   f_after = {grant[N-2:0], grant[N-1]};

    reg [N-1:0]  f_after_q;
    reg          f_rst_q;
    reg          f_any_q;
    reg [PW-1:0] f_ptr_q;

    always @(posedge clk) begin
        f_after_q <= f_after;
        f_rst_q   <= rst_n;
        f_any_q   <= |grant;
        f_ptr_q   <= ptr;
    end

    always @(*) begin
        if (f_past_valid) begin
            assert (ptr <= LAST);
            assert ((grant & (grant - 1'b1)) == {N{1'b0}});
            assert ((grant & ~req) == {N{1'b0}});
            assert ((req == {N{1'b0}}) || (grant != {N{1'b0}}));
            assert (grant == f_ref);
            if (!f_rst_q)
                assert (ptr == {PW{1'b0}});
            else if (!f_any_q)
                assert (ptr == f_ptr_q);
            else
                assert (f_after_q[ptr]);
        end
    end

    // Fairness: cycles waited with req held, and the induction invariant
    // wait + distance(ptr -> requester) <= N-1.
    genvar f_i;
    generate
        for (f_i = 0; f_i < N; f_i = f_i + 1) begin : g_fair
            reg  [PW:0] f_wait;
            wire [PW:0] f_dist;
            initial f_wait = {(PW+1){1'b0}};
            assign f_dist = (f_i >= ptr) ? (f_i - ptr) : (f_i + N - ptr);
            always @(posedge clk) begin
                if (!rst_n || !req[f_i] || grant[f_i]) f_wait <= {(PW+1){1'b0}};
                else                                   f_wait <= f_wait + 1'b1;
            end
            always @(*) begin
                if (f_past_valid) begin
                    assert (f_wait <= LAST);
                    assert ((f_wait + f_dist) <= LAST);
                end
            end
        end
    endgenerate
`endif

endmodule

`default_nettype wire
=== END FILE ===
