// Self-checking testbench for rr_arbiter, at N 4 and N 5.
// Checks grant every cycle against a reference pointer model, checks that no
// held request waits N cycles, and fails the run on missing coverage.
`timescale 1ns / 1ps

module rr_arbiter_tb_harness #(
    parameter integer N    = 4,
    parameter [31:0]  SEED = 32'h1234_5678
) (
    input  wire        clk,
    output reg  [31:0] passed,
    output reg  [31:0] failed,
    output reg         done
);
    localparam [N-1:0] ALL  = {N{1'b1}};
    localparam [N-1:0] NONE = {N{1'b0}};
    localparam [N-1:0] ONE  = {{(N-1){1'b0}}, 1'b1};

    reg          rst_n;
    reg  [N-1:0] req;
    wire [N-1:0] grant;

    rr_arbiter #(.N(N)) dut (
        .clk   (clk),
        .rst_n (rst_n),
        .req   (req),
        .grant (grant)
    );

    // Reference model state.
    integer     m_ptr;
    integer     exp_winner;
    reg [N-1:0] exp_grant;

    // Fairness and coverage state.
    integer     wait_cnt [0:N-1];
    reg [N-1:0] prev_req;
    reg [31:0]  lfsr;
    reg         rot_en;
    integer     rot_idx;
    reg         seen_run;
    integer     cov_idle;
    integer     cov_all;
    integer     cov_held;
    integer     cov_maxwait;
    integer     cov_rst_traffic;
    integer     cov_rot;
    reg [N-1:0] cov_alone;

    integer c;
    integer h;
    integer i;
    integer hold;

    task lfsr_step;
        integer s;
        begin
            for (s = 0; s < 7; s = s + 1)
                lfsr = {lfsr[30:0], lfsr[31] ^ lfsr[21] ^ lfsr[1] ^ lfsr[0]};
        end
    endtask

    // Reference: first requester at or after m_ptr, wrapping at N.
    task model_grant;
        integer k;
        integer idx;
        begin
            exp_grant  = NONE;
            exp_winner = -1;
            for (k = 0; k < N; k = k + 1) begin
                idx = (m_ptr + k) % N;
                if ((exp_winner < 0) && req[idx]) begin
                    exp_winner     = idx;
                    exp_grant[idx] = 1'b1;
                end
            end
        end
    endtask

    // One clock cycle: drive at the falling edge, check, update the model at
    // the rising edge.
    task drive_cycle;
        input [N-1:0] r_in;
        input         rn_in;
        integer k;
        reg     fair_ok;
        begin
            @(negedge clk);
            req   = r_in;
            rst_n = rn_in;
            #1;
            model_grant;
            if (grant === exp_grant) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("N=%0d t=%0t: req=%b rst_n=%b model ptr=%0d grant=%b expected=%b",
                       N, $time, r_in, rn_in, m_ptr, grant, exp_grant);
            end

            if (rot_en) begin
                if (grant === (ONE << rot_idx)) begin
                    passed  = passed + 1;
                    cov_rot = cov_rot + 1;
                end else begin
                    failed = failed + 1;
                    $error("N=%0d t=%0t: rotation step expected requester %0d, grant=%b",
                           N, $time, rot_idx, grant);
                end
            end

            fair_ok = 1'b1;
            for (k = 0; k < N; k = k + 1) begin
                if (rn_in && r_in[k] && (wait_cnt[k] > 0) &&
                    (((r_in ^ prev_req) & ~(ONE << k)) != NONE))
                    cov_held = cov_held + 1;
                if (rn_in && r_in[k] && (grant[k] !== 1'b1)) begin
                    wait_cnt[k] = wait_cnt[k] + 1;
                    if (wait_cnt[k] == N - 1) cov_maxwait = cov_maxwait + 1;
                    if (wait_cnt[k] > N - 1) begin
                        fair_ok = 1'b0;
                        $error("N=%0d t=%0t: requester %0d held req %0d cycles without a grant",
                               N, $time, k, wait_cnt[k]);
                    end
                end else begin
                    wait_cnt[k] = 0;
                end
            end
            if (fair_ok) passed = passed + 1;
            else         failed = failed + 1;

            if (rn_in && (r_in == NONE)) cov_idle = cov_idle + 1;
            if (rn_in && (r_in == ALL))  cov_all  = cov_all + 1;
            if (rn_in && (r_in != NONE) && ((r_in & (r_in - ONE)) == NONE))
                cov_alone = cov_alone | r_in;
            if (!rn_in && (r_in != NONE) && seen_run)
                cov_rst_traffic = cov_rst_traffic + 1;
            if (rn_in) seen_run = 1'b1;
            prev_req = r_in;

            @(posedge clk);
            if (!rn_in)                m_ptr = 0;
            else if (exp_winner >= 0)  m_ptr = (exp_winner + 1) % N;
        end
    endtask

    task cover_check;
        input integer         hits;
        input [8*32-1:0]      name;
        begin
            if (hits > 0) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("N=%0d: coverage point '%0s' was never reached", N, name);
            end
        end
    endtask

    initial begin
        passed          = 32'd0;
        failed          = 32'd0;
        done            = 1'b0;
        rst_n           = 1'b0;
        req             = NONE;
        m_ptr           = 0;
        exp_winner      = -1;
        exp_grant       = NONE;
        prev_req        = NONE;
        lfsr            = SEED;
        rot_en          = 1'b0;
        rot_idx         = 0;
        seen_run        = 1'b0;
        cov_idle        = 0;
        cov_all         = 0;
        cov_held        = 0;
        cov_maxwait     = 0;
        cov_rst_traffic = 0;
        cov_rot         = 0;
        cov_alone       = NONE;
        for (i = 0; i < N; i = i + 1) wait_cnt[i] = 0;

        // Two reset edges so the pointer is known before checking starts.
        @(posedge clk);
        @(posedge clk);
        m_ptr = 0;

        // Reset with no requests.
        drive_cycle(NONE, 1'b0);
        drive_cycle(NONE, 1'b0);

        // No requests out of reset.
        for (c = 0; c < 3; c = c + 1) drive_cycle(NONE, 1'b1);

        // Each requester alone.
        for (i = 0; i < N; i = i + 1) begin
            drive_cycle(ONE << i, 1'b1);
            drive_cycle(ONE << i, 1'b1);
        end

        // Reset during traffic, then strict rotation 0..N-1 with everyone
        // requesting (also the longest fair wait, N-1, for requester N-1).
        drive_cycle(ALL, 1'b0);
        rot_en = 1'b1;
        for (c = 0; c < 3 * N; c = c + 1) begin
            rot_idx = c % N;
            drive_cycle(ALL, 1'b1);
        end
        rot_en = 1'b0;

        // A held request among changing others, for two different holders.
        for (h = 0; h < 2; h = h + 1) begin
            hold = (h == 0) ? (N - 1) : 1;
            for (c = 0; c < 6 * N; c = c + 1) begin
                lfsr_step;
                drive_cycle(lfsr[N-1:0] | (ONE << hold), 1'b1);
            end
        end

        // Reset in the middle of traffic, held for two cycles.
        lfsr_step;
        drive_cycle(lfsr[N-1:0] | ONE, 1'b0);
        lfsr_step;
        drive_cycle(lfsr[N-1:0] | ONE, 1'b0);

        // Random traffic with occasional resets.
        for (c = 0; c < 500; c = c + 1) begin
            lfsr_step;
            drive_cycle(lfsr[N-1:0], (lfsr[20:16] != 5'd0));
        end

        // Coverage: every case named by the interface spec must be reached.
        cover_check(cov_idle,        "no requests");
        cover_check((cov_alone == ALL) ? 1 : 0, "each requester alone");
        cover_check(cov_all,         "everyone requesting");
        cover_check(cov_held,        "held request among changing others");
        cover_check(cov_maxwait,     "longest fair wait N-1");
        cover_check(cov_rst_traffic, "reset during traffic");
        cover_check((cov_rot >= 2 * N) ? 1 : 0, "strict rotation after reset");

        done = 1'b1;
    end
endmodule

module rr_arbiter_tb;
    reg clk;
    initial clk = 1'b0;
    always #5 clk = ~clk;

    wire [31:0] p4;
    wire [31:0] f4;
    wire [31:0] p5;
    wire [31:0] f5;
    wire        d4;
    wire        d5;

    rr_arbiter_tb_harness #(.N(4), .SEED(32'h1234_5678)) h4 (
        .clk    (clk),
        .passed (p4),
        .failed (f4),
        .done   (d4)
    );

    rr_arbiter_tb_harness #(.N(5), .SEED(32'h0BAD_F00D)) h5 (
        .clk    (clk),
        .passed (p5),
        .failed (f5),
        .done   (d5)
    );

    reg [8*64-1:0] nonce;
    reg            verdict_given;
    integer        passed;
    integer        failed;

    task give_verdict;
        input integer extra_fail;
        begin
            if (!verdict_given) begin
                verdict_given = 1'b1;
                passed = p4 + p5;
                failed = f4 + f5 + extra_fail;
                $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
                $finish;
            end
        end
    endtask

    initial begin
        verdict_given = 1'b0;
        nonce = {(8*64){1'b0}};
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "unset";
        wait (d4 && d5);
        #1;
        give_verdict(0);
    end

    initial begin
        #1000000;
        $error("timeout: the arbiter harnesses did not finish");
        give_verdict(1);
    end
endmodule
=== END FILE ===
